import { test, expect } from '@playwright/test';

test.describe('Async Data Fetching Non-Blocking Render', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to a page that demonstrates async data fetching
    await page.goto('https://example.com');
  });

  test('should render initial page content before async data loads', async ({ page }) => {
    // Set up a listener to track when async data request completes
    let asyncDataLoaded = false;
    page.on('response', (response) => {
      if (response.url().includes('api') || response.url().includes('data')) {
        asyncDataLoaded = true;
      }
    });

    // Navigate to page with async data
    await page.goto('https://example.com/async-page');

    // Verify initial content is rendered immediately
    const initialContent = page.getByRole('heading', { level: 1 });
    await expect(initialContent).toBeVisible({ timeout: 2000 });

    // Verify page is interactive before async data loads
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();

    // Wait for async data to load
    await page.waitForLoadState('networkidle');

    // Verify async content appears after initial render
    const asyncContent = page.getByText(/loaded|fetched|data/i);
    await expect(asyncContent).toBeVisible({ timeout: 5000 });
  });

  test('should display loading state while async data is fetching', async ({ page }) => {
    await page.goto('https://example.com/async-page');

    // Check for initial skeleton or loading indicator
    const loadingIndicator = page.getByRole('status');

    // Initial content should be visible
    const heading = page.getByRole('heading');
    await expect(heading).toBeVisible();

    // Wait for async operation to complete
    await page.waitForLoadState('networkidle');

    // Verify final content is rendered
    const finalContent = page.getByRole('main');
    await expect(finalContent).toBeVisible();

    // Verify page remains responsive during async operations
    const button = page.getByRole('button').first();
    if (await button.isVisible()) {
      await expect(button).toBeEnabled();
    }
  });

  test('should not block user interactions during async data fetch', async ({ page }) => {
    await page.goto('https://example.com/async-page');

    // Verify interactive elements are available immediately
    const interactiveButton = page.getByRole('button', { name: /click|submit|action/i }).first();

    if (await interactiveButton.isVisible()) {
      // Button should be clickable even while async data is loading
      await expect(interactiveButton).toBeEnabled();

      // Click button while async operations might be in progress
      await interactiveButton.click();

      // Verify page responds to user action
      await page.waitForLoadState('networkidle');

      // Verify no errors occurred
      const errorMessage = page.getByRole('alert');
      await expect(errorMessage).not.toBeVisible();
    }
  });

  test('should render page structure before async content population', async ({ page }) => {
    await page.goto('https://example.com/async-page');

    // Verify page layout structure is immediately available
    const mainSection = page.getByRole('main');
    await expect(mainSection).toBeVisible({ timeout: 1000 });

    // Verify header is rendered
    const header = page.getByRole('banner');
    if (await header.isVisible()) {
      await expect(header).toBeVisible();
    }

    // Verify navigation is available
    const nav = page.getByRole('navigation');
    if (await nav.isVisible()) {
      await expect(nav).toBeVisible();
    }

    // Wait for async data to populate
    await page.waitForLoadState('networkidle');

    // Verify content areas are populated
    const contentArea = page.getByRole('article');
    if (await contentArea.isVisible()) {
      await expect(contentArea).toBeVisible();
    }
  });
});
